    declared = CaseParticipant.objects.filter(
        role="ACCUSED",
        person__isnull=True,
        institution__isnull=False,
        contact_details_unknown_declared=True,
    )
    groups = declared.filter(is_active=True).values_list("case_id", "institution_id").distinct()
